// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        // owner starts at address(0); any fuzzed actor is (almost surely) not the owner
        vm.assume(actor != address(this) && actor != address(c));
        address ownerBefore = c.owner();

        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // Universal rule: a non-owner cannot change ownership — call reverts
        // and the owner is unchanged.
        assertTrue(!ok && c.owner() == ownerBefore);
    }
}
